messages.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "type": [
        "string",
        "null"
      ]
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    }
  },
  "required": [
    "items"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentExpression",
  "description": "Expression variant of [`RichContent`] for dynamic content.",
  "anyOf": [
    {
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "description": "Multi-part content expressions.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.WithExpression.agent.completions.message.RichContentPartExpression"
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.SystemMessageExpression",
  "description": "Expression variant of [`SystemMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.",
      "$ref": "functions.expression.WithExpression.agent.completions.message.SimpleContentExpression"
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
          "$ref": "functions.expression.WithExpression.Nullable_string"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "content"
  ]
}
